package cpptable

// TestCppRetainKeepsDepth128 holds RETAIN-UNKNOWN to §4's ONE NESTING BOUND
// (docs/SPEC-TABLES.md §4, §6.6): the retaining load keeps an unknown field
// nested to the bound and the retaining save writes it back byte for byte, while
// a vector one level past the bound is refused by the retaining load too. A
// depth is not a retention capacity, so a field the plain read accepts is never
// dropped for its depth. The read vectors and the refused vectors are the
// framing corpus's own, generated by the harness and read here rather than
// copied.

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/mas-bandwidth/schema/v2/internal/slowtest"
	"github.com/mas-bandwidth/schema/v2/internal/tabletext"
	"github.com/mas-bandwidth/schema/v2/internal/tablewire"
)

func TestCppRetainKeepsDepth128(t *testing.T) {
	t.Parallel()
	slowtest.Gate(t, "a C++ compiler (it builds and runs the generated C++)")
	cxx := os.Getenv("CXX")
	if cxx == "" {
		cxx = "c++"
	}
	if _, err := exec.LookPath(cxx); err != nil {
		if os.Getenv("SCHEMA_REQUIRE_CORPUS") != "" {
			t.Fatalf("SCHEMA_REQUIRE_CORPUS is set and %s is not on PATH: %v", cxx, err)
		}
		t.Skipf("%s is not on PATH: %v", cxx, err)
	}

	root, err := filepath.Abs(filepath.Join("..", "..", ".."))
	if err != nil {
		t.Fatal(err)
	}
	u := loadHeldUnitPaths(t, root, []string{filepath.Join("tables", "pointers")})
	model := tabletext.NewModel(u)
	scene := model.Lookup("Scene")
	if scene == nil {
		t.Fatal("graphdemo does not declare Scene")
	}
	framingDir := filepath.Join(root, "testdata", "wire", "tables", "framing")
	read := func(name string) []byte {
		t.Helper()
		data, err := os.ReadFile(filepath.Join(framingDir, name+".bin"))
		if err != nil {
			t.Fatalf("read %s: %v", name, err)
		}
		return data
	}

	reads := []string{"depth_tables_128", "depth_arrays_128", "depth_union_tables_64", "depth_keyed_128"}
	refused := []string{"depth_tables_129", "depth_arrays_129", "depth_union_tables_65", "depth_keyed_129", "depth_tables_5000"}

	// The engine is asked first, so a vector is held to the rule and not to an
	// assumption about what it carries.
	for _, name := range reads {
		var report tabletext.Report
		ok, err := tablewire.Decode(model, model.New(scene), read(name), &report)
		if !ok || report.Unknown != 1 {
			t.Errorf("engine %s: ok=%v err=%v unknown=%d, want ok=true unknown=1", name, ok, err, report.Unknown)
		}
	}
	for _, name := range refused {
		var report tabletext.Report
		ok, err := tablewire.Decode(model, model.New(scene), read(name), &report)
		if ok {
			t.Errorf("engine %s: accepted a depth the binary bound refuses (err=%v)", name, err)
		}
	}

	var body strings.Builder
	for i, name := range reads {
		wire := read(name)
		fmt.Fprintf(&body, "    const uint8_t wire_%d[] = { %s };\n", i, cppBytes(wire))
		fmt.Fprintf(&body, `
    {
        const int64_t need = SceneLoadMeasure( wire_%[1]d, (int64_t) sizeof( wire_%[1]d ) );
        if ( need < 0 ) { printf( "%[2]s: the plain load measure refused a readable depth\n" ); return 1; }
        std::vector<uint8_t> region( (size_t) need + 64 );
        uint8_t * aligned = region.data();
        while ( ( (uintptr_t) aligned & 63 ) != 0 ) { aligned++; }
        TableReport plain_report; memset( &plain_report, 0, sizeof( plain_report ) );
        const Scene * plain = SceneLoad( aligned, need, wire_%[1]d, (int64_t) sizeof( wire_%[1]d ), &plain_report );
        if ( plain == NULL ) { printf( "%[2]s: the plain load refused a readable depth\n" ); return 1; }

        alignas( 64 ) static uint8_t retain_region[ 1 << 18 ];
        static uint8_t store[ 1 << 16 ];
        TableRetain::Id ids[16];
        TableRetain retain;
        retain.bytes = store; retain.capacity = (int64_t) sizeof( store );
        retain.ids = ids; retain.id_capacity = 16;
        TableReport report; memset( &report, 0, sizeof( report ) );
        const Scene * value = SceneLoadRetain( retain_region, (int64_t) sizeof( retain_region ), wire_%[1]d, (int64_t) sizeof( wire_%[1]d ), &retain, &report );
        if ( value == NULL ) { printf( "%[2]s: the retaining load refused a readable depth\n" ); return 1; }
        if ( report.retain_lost != 0 ) { printf( "%[2]s: the retaining load lost an unknown field (lost=%%d)\n", (int) report.retain_lost ); return 1; }

        std::vector<uint8_t> saved( 1 << 18 );
        TableReport save_report; memset( &save_report, 0, sizeof( save_report ) );
        const int64_t wrote = SceneSaveRetain( value, &retain, saved.data(), (int64_t) saved.size(), &save_report );
        if ( wrote != (int64_t) sizeof( wire_%[1]d ) || memcmp( saved.data(), wire_%[1]d, sizeof( wire_%[1]d ) ) != 0 )
            { printf( "%[2]s: the retained save changed the file bytes (wrote %%lld of %%zu)\n", (long long) wrote, sizeof( wire_%[1]d ) ); return 1; }
        if ( save_report.retain_lost != 0 ) { printf( "%[2]s: the retained save lost an unknown field (lost=%%d)\n", (int) save_report.retain_lost ); return 1; }
    }
`, i, name)
	}
	for i, name := range refused {
		wire := read(name)
		fmt.Fprintf(&body, "    const uint8_t refused_%d[] = { %s };\n", i, cppBytes(wire))
		fmt.Fprintf(&body, `
    {
        alignas( 64 ) static uint8_t refused_region_%[1]d[ 1 << 18 ];
        static uint8_t refused_store_%[1]d[ 1 << 16 ];
        TableRetain::Id refused_ids_%[1]d[16];
        TableRetain retain;
        retain.bytes = refused_store_%[1]d; retain.capacity = (int64_t) sizeof( refused_store_%[1]d );
        retain.ids = refused_ids_%[1]d; retain.id_capacity = 16;
        TableReport report; memset( &report, 0, sizeof( report ) );
        const Scene * value = SceneLoadRetain( refused_region_%[1]d, (int64_t) sizeof( refused_region_%[1]d ), refused_%[1]d, (int64_t) sizeof( refused_%[1]d ), &retain, &report );
        if ( value != NULL ) { printf( "%[2]s: the retaining load accepted a refused depth\n" ); return 1; }
    }
`, i, name)
	}

	out, err := cppHeldRun(t, u, body.String())
	if err != nil {
		t.Fatalf("%v\n%s", err, out)
	}
}
